            ['section' => 'Comprehension', 'type' => 'matching', 'question_text' => 'Match each figure to their part.', 'match_pairs' => [['left' => 'Athos', 'right' => 'Pale wounded leader hiding a tragic marriage'], ['left' => 'Porthos', 'right' => 'Showy giant hoping to marry a wealthy widow'], ['left' => 'Aramis', 'right' => 'Gentle dreamer torn between sword and altar'], ['left' => 'Milady', 'right' => 'Beautiful agent marked with the fleur-de-lis']]],
            ['section' => 'Comprehension', 'type' => 'mcq', 'question_text' => 'Why did the queen need her diamond studs back?', 'option_a' => 'The cardinal arranged for her to be asked to wear them while two were stolen', 'option_b' => 'The king demanded them as a birthday gift', 'option_c' => 'Buckingham wanted them returned to France', 'option_d' => 'They held a secret map of the palace', 'correct_option' => 'a'],
