            ['section' => 'Comprehension', 'type' => 'matching', 'question_text' => 'Match each figure to their part.', 'match_pairs' => [['left' => 'Fernand', 'right' => 'Jealous rival who stole Mercedes while Edmond rotted away'], ['left' => 'Danglars', 'right' => 'Envious shipmate whose anonymous letter began it all'], ['left' => 'Villefort', 'right' => 'Ambitious prosecutor who jailed an innocent man to save himself'], ['left' => 'Caderousse', 'right' => 'Greedy neighbor whose love of gold destroyed him']]],
            ['section' => 'Comprehension', 'type' => 'mcq', 'question_text' => 'Why does Villefort imprison an innocent man?', 'option_a' => 'The letter would expose his father and ruin him', 'option_b' => 'He believes Dantes stole the cargo', 'option_c' => 'Mercedes asked him to stop the wedding', 'option_d' => 'The king ordered every sailor questioned', 'correct_option' => 'a'],
            ['section' => 'Comprehension', 'type' => 'mcq', 'question_text' => 'How does Dantes escape the Chateau d\'If?', 'option_a' => 'He takes the dead abbe\'s place in a sack thrown into the sea', 'option_b' => 'He digs a tunnel to the shore over fourteen years', 'option_c' => 'He bribes a guard with the treasure map', 'option_d' => 'He swims out during a violent storm', 'correct_option' => 'a'],
