            ['section' => 'Comprehension', 'type' => 'sequence', 'question_text' => 'Put the events of the story in order.', 'sequence_items' => ['Tom tricks the whole village into whitewashing Aunt Polly\'s fence', 'Tom and Huck witness a murder in the graveyard at midnight', 'Tom runs away to Jackson\'s Island to play pirate', 'The three pirates march into church at their own funeral', 'Tom testifies in court and Injun Joe leaps through a window']],
            ['section' => 'Comprehension', 'type' => 'matching', 'question_text' => 'Match each character to their part.', 'match_pairs' => [['left' => 'Aunt Polly', 'right' => 'Stern but soft-hearted guardian who loves Tom dearly'], ['left' => 'Becky Thatcher', 'right' => 'New girl in town whom Tom falls for'], ['left' => 'Huckleberry Finn', 'right' => 'Town outcast and Tom\'s treasure-hunting partner'], ['left' => 'Injun Joe', 'right' => 'Half-breed killer haunted by fear of discovery']]],
            ['section' => 'Comprehension', 'type' => 'mcq', 'question_text' => 'How did Tom get the fence whitewashed?', 'option_a' => 'He made other boys pay treasures for the honor of painting it', 'option_b' => 'He finished it alone before breakfast', 'option_c' => 'Aunt Polly hired a man to do it', 'option_d' => 'Ben Rogers did it all as a favor', 'correct_option' => 'a'],
            ['section' => 'Comprehension', 'type' => 'mcq', 'question_text' => 'How much money did the treasure chest hold?', 'option_a' => 'More than twelve thousand dollars in gold', 'option_b' => 'Exactly one thousand silver coins', 'option_c' => 'A handful of old Spanish pennies', 'option_d' => 'Nothing but worthless paper', 'correct_option' => 'a'],
